    if(!$nama||!$mulai||!$selesai||strtotime($selesai)<=strtotime($mulai))$error='Lengkapi data. Waktu selesai harus setelah waktu mulai.';
    else{if($period){$st=$pdo->prepare('UPDATE periode_voting SET nama_periode=?,tanggal_mulai=?,tanggal_selesai=?,status=? WHERE id=?');$st->execute([$nama,$mulai,$selesai,$status,$period['id']]);}else{$st=$pdo->prepare('INSERT INTO periode_voting (nama_periode,tanggal_mulai,tanggal_selesai,status) VALUES (?,?,?,?)');$st->execute([$nama,$mulai,$selesai,$status]);}flash('success','Periode voting berhasil disimpan.');redirect('admin/periode.php');}}
